export async function searchOwnersByLastName(page, lastName) {
    await page.locator("#lastName").fill(lastName);
    await page.getByRole("button", { name: "Find Owner" }).click();
}

export async function clearOwnerSearch(page) {
    await page.locator("#clearSearch").click();
}

export async function submitOwnerSearch(page) {
    await page.getByRole("button", { name: "Find Owner" }).click();
}
